<?php require __DIR__.'/bootstrap.php';require_login();$tid=(int)($_GET['tour_id']??0);if(!$tid)$tid=require_tour();$departure=trim((string)($_GET['departure']??''));
$t=tour_row($tid);
$sql="SELECT p.*,b.name bus_name,b.bus_number,s.seat_no FROM passengers p JOIN buses b ON b.id=p.bus_id JOIN seats s ON s.id=p.seat_id WHERE p.tour_id=? AND p.status='ACTIVE'";$params=[$tid];if($departure!==''){$sql.=" AND COALESCE(NULLIF(TRIM(p.departure),''),'Not Set')=?";$params[]=$departure;}$sql.=" ORDER BY CASE WHEN p.departure IS NULL OR TRIM(p.departure)='' THEN 1 ELSE 0 END,p.departure,b.id,s.row_no,s.col_no";$q=db()->prepare($sql);$q->execute($params);$rows=$q->fetchAll();
$counts=[];foreach($rows as $p){$d=trim((string)($p['departure']??''))?:'Not Set';$counts[$d]=($counts[$d]??0)+1;}
?><!doctype html><html><head><?php include __DIR__.'/partials/head.php';?><style>@media print{.no-print{display:none!important}body{background:#fff!important}.print-card{box-shadow:none!important;border:0!important}.page-title{margin-top:0}.print-table{font-size:12px}.print-table th,.print-table td{padding:7px 8px!important}.summary-grid{grid-template-columns:repeat(4,1fr)!important}}.summary-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin:14px 0}.summary-box{border:1px solid #dfe7e1;border-radius:10px;padding:10px 12px}.summary-box b{display:block;font-size:18px}.summary-box span{font-size:12px;color:#64748b}.print-table{width:100%;border-collapse:collapse}.print-table th,.print-table td{border:1px solid #dfe3e8;padding:8px;text-align:left}.print-table th{background:#f4f7f5}.group-row td{background:#eaf5ed;font-weight:800}</style></head><body><main class="wrap"><div class="head no-print"><a class="btn secondary" href="passengers.php">Back</a><button class="btn primary" onclick="window.print()">Print This List</button></div><section class="card print-card"><div class="head page-title"><div><div class="eyebrow">GMJS TOUR — BOARDING LIST</div><h1><?=h($t['name']??'Tour')?></h1><p class="muted"><?=h($t['start_date']??'')?> → <?=h($t['end_date']??'')?></p></div><div><b><?=h($departure!==''?$departure:'All Departure Places')?></b><br><span class="muted"><?=count($rows)?> passenger<?=count($rows)===1?'':'s'?></span></div></div><div class="summary-grid"><?php foreach($counts as $d=>$n):?><div class="summary-box"><span><?=h($d)?></span><b><?=$n?></b></div><?php endforeach;?></div><table class="print-table"><thead><tr><th>#</th><th>Seat</th><th>Passenger Name</th><th>Phone</th><th>Departure Place</th><th>Bus</th><th>Room</th></tr></thead><tbody><?php $i=0;$last='';foreach($rows as $p):$i++;$d=trim((string)($p['departure']??''))?:'Not Set';if($departure===''&&$d!==$last):$last=$d;?><tr class="group-row"><td colspan="7"><?=h($d)?> — <?=$counts[$d]?> passenger<?=($counts[$d]===1?'':'s')?></td></tr><?php endif;?><tr><td><?=$i?></td><td><b><?=h($p['seat_no'])?></b></td><td><?=h($p['name'])?></td><td><?=h($p['phone'])?></td><td><?=h($d)?></td><td><?=h($p['bus_name'])?><?=!empty($p['bus_number'])?' · '.h($p['bus_number']):''?></td><td><?=h(room_label($p['room_type']))?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="7">No passengers found for this departure place.</td></tr><?php endif;?></tbody></table></section></main></body></html>
